// Download .
// @router /anonymous/download/:code [GET]
func Download(ctx context.Context, c *app.RequestContext) {
	code := c.Param("code")
	if code == "" {
		resp.NewErrorWithMessage(c, errcode.CodeInvalidParam, "code required")
		return
	}
	// 下载闸门：download.require_login（服务端 enforce）
	if err := gate.CheckDownloadLogin(nil); err != nil {
		resp.NewTypedError(c, err)
		return
	}
	// 安全修复（P0，2026-10-03）：此前的实现是对任意 code 无条件签发下载令牌
	// 后 302——而 /share/download 对持有效令牌的请求跳过密码校验，等于密码保护
	// 形同虚设（令牌签发 oracle）。现在仅对"存在/未过期/未管控/无密码"的分享
	// 签发令牌；密码保护分享一律拒绝并引导走取件页。
	// Peek 已内置 blocked/待审校验（BlockedError）
	_, fc, err := getService().Peek(ctx, code)
	if err != nil {
		var blocked *anonapp.BlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return
		}
		if errors.Is(err, anonapp.ErrCodeNotFound) {
			resp.NewErrorByCode(c, errcode.CodePickupCodeNotFound)
			return
		}
		// 基础设施故障（如 Redis 不可达）不能伪装成"码不存在"——
		// 那会把服务故障遮蔽成业务 404，调用方无法区分
		resp.NewErrorWithMessage(c, errcode.CodeInternal, sanitizeInternalMsg(err))
		return
	}
	if fc.IsExpired() {
		resp.NewErrorByCode(c, errcode.CodePickupCodeExpired)
		return
	}
	if fc.IsBlockedShare() {
		resp.NewTypedError(c, &anonapp.BlockedError{Status: fc.Status})
		return
	}
	if fc.RequireAuth {
		c.JSON(consts.StatusUnauthorized, map[string]interface{}{
			"code":    errcode.CodeSharePasswordWrong,
			"message": "该分享受密码保护，请通过取件页输入密码后下载",
			"data":    map[string]interface{}{"has_password": true},
		})
		return
	}
	target := "/share/download?code=" + fc.Code
	if tk := security.GenerateDownloadToken(fc.Code); tk != "" {
		target += "&token=" + tk
	}
	c.Redirect(consts.StatusFound, []byte(target))
}

// SearchByCode 按码查询分享信息（不下载、不扣次数）。
// @router /anonymous/search/:code [GET]
func SearchByCode(ctx context.Context, c *app.RequestContext) {
	code := c.Param("code")
	if code == "" {
		resp.NewErrorWithMessage(c, errcode.CodeInvalidParam, "code required")
		return
	}
	// 下载闸门（治理）：download.require_login 时元数据（文件名/大小/统计）不向匿名暴露
	if err := gate.CheckDownloadLogin(nil); err != nil {
		resp.NewTypedError(c, err)
		return
	}
	meta, fc, err := getService().Peek(ctx, code)
	if err != nil {
		var blocked *anonapp.BlockedError
		if errors.As(err, &blocked) {
			resp.NewTypedError(c, blocked)
			return
		}
		if errors.Is(err, anonapp.ErrCodeNotFound) {
			resp.NewErrorByCode(c, errcode.CodePickupCodeNotFound)
			return
		}
		// 同 Download：基础设施故障不得遮蔽为"码不存在"
		resp.NewErrorWithMessage(c, errcode.CodeInternal, sanitizeInternalMsg(err))
		return
	}
	maxCount := int32(0)
	if fc.ExpiredCount == -1 {
		maxCount = 0 // 无限在前端通常显示为 0 或特殊值
	} else {
		maxCount = int32(fc.UsedCount + fc.ExpiredCount)
	}
	expireStr := ""
	if fc.ExpiredAt != nil {
		expireStr = fc.ExpiredAt.Format(time.RFC3339)
	}
	// 密码保护分享的最小化返回（2026-10-05 审计 P2）：与 /share/metadata 同策略，
	// 输对密码前不泄露文件名/大小/取件统计——该端点公开且此前不在任何限流桶，
	// 构成免密码元数据预言机。
	if fc.RequireAuth {
		resp.Success(c, &anonmodel.SearchByCodeData{
			RequirePassword: true,
		})
		return
	}
	resp.Success(c, &anonmodel.SearchByCodeData{
		FileName:        meta.FileName,
		FileSize:        meta.FileSize,
		CreatedAt:       fc.CreatedAt.Format(time.RFC3339),
		ExpireAt:        expireStr,
		PickupCount:     int32(fc.UsedCount),
		MaxPickupCount:  maxCount,
		RequirePassword: fc.RequireAuth,
	})
}
